27	/* Badge */
28	.badge {
29	  display: inline-flex;
30	  align-items: center;
31	  justify-content: center;
32	  background: rgba(33, 207, 255, 0.12);
33	  border: 1px solid rgba(33, 207, 255, 0.25);
34	  border-radius: 100px;
35	  padding: 6px 18px;
36	  margin-bottom: 24px;
37	}
38	
39	.badgeText {
40	  font-family: 'Roobert PRO', Arial, sans-serif;
41	  font-size: 13px;
42	  font-weight: 700;
43	  line-height: 1;
44	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
45	  -webkit-background-clip: text;
46	  -webkit-text-fill-color: transparent;
47	  background-clip: text;
48	  text-transform: uppercase;
49	  letter-spacing: 0.06em;
50	}
51	
52	/* Heading */
53	.heading {
54	  color: #ffffff;
55	  font-family: 'Roobert PRO', Arial, sans-serif;
56	  font-size: clamp(2.25rem, 5vw, 3.75rem);
57	  font-weight: 700;
58	  line-height: 1.1;
59	  margin-bottom: 20px;
60	}
61	
62	/* Subtitle */
63	.subtitle {
64	  color: rgba(255, 255, 255, 0.65);
65	  font-family: 'Roobert PRO', Arial, sans-serif;
66	  font-size: 17px;
67	  font-weight: 400;
68	  line-height: 1.7;
69	  max-width: 640px;
70	  margin-left: auto;
71	  margin-right: auto;
72	  margin-bottom: 40px;
73	}
74	
75	/* CTA row */
76	.ctaRow {
77	  display: flex;
78	  align-items: center;
79	  justify-content: center;
80	}
81	
82	.ctaButton {
83	  display: inline-flex;
84	  align-items: center;
85	  justify-content: center;
86	  color: #fff;
87	  font-family: 'Roobert PRO', Arial, sans-serif;
88	  font-size: 1rem;
89	  font-weight: 700;
90	  line-height: 1.75rem;
91	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
92	  border: 2px solid transparent;
93	  border-radius: 0.75rem;
94	  padding: 0.75rem 2rem;
95	  text-decoration: none;
96	  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
97	  transition: filter 0.2s, box-shadow 0.2s;
98	}
99	
100	.ctaButton:hover {
101	  filter: brightness(1.1);
102	  box-shadow: 0 4px 24px rgba(33, 207, 255, 0.35);
103	}
104	
105	/* Gallery row */
106	.galleryRow {
107	  display: grid;
108	  grid-template-columns: 1fr 1fr 1fr;
109	  gap: 16px;
110	  align-items: flex-end;
111	}
112	
113	.galleryCard {
114	  position: relative;
115	  border-radius: 16px 16px 0 0;
116	  overflow: hidden;
117	  height: 280px;
118	}
119	
120	/* Subtle stagger/offset per card */
121	.galleryCard1 {
122	  transform: translateY(8px);
123	  height: 260px;
124	}
125	
126	.galleryCard2 {
127	  height: 300px;
128	}
129	
130	.galleryCard3 {
131	  transform: translateY(12px);
132	  height: 250px;
133	}
134	
135	.galleryImage {
136	  object-fit: cover;
137	  object-position: center top;
138	  transition: transform 0.4s ease;
139	}
140	
141	.galleryCard:hover .galleryImage {
142	  transform: scale(1.04);
143	}
